-- Confirmed paid upgrade: solar 5 kW standard -> 10 kW (price to fill in).
update public.spec_items s set note = 'มาตรฐาน 5 kW (ตามสเปกที่ยืนยัน) · ขนาดจริงตามวิศวกร'
  from public.projects p
 where p.id = s.project_id and p.code = 'PROJECT-001' and s.item_no = 'RF-15' and s.created_by is null;
insert into public.spec_options (organization_id, project_id, item_id, seq, name, size, note)
select s.organization_id, s.project_id, s.id, 1, 'โซลาร์เซลล์ 10 kW', '10 kWp', 'อัปเกรดมีค่าใช้จ่าย ใส่ราคาก่อนเสนอลูกค้า'
  from public.spec_items s join public.projects p on p.id = s.project_id
 where p.code = 'PROJECT-001' and s.item_no = 'RF-15'
   and not exists(select 1 from public.spec_options o where o.item_id = s.id and o.name = 'โซลาร์เซลล์ 10 kW');
